public static int hoehe(BinTree b) {
    if (b.isEmpty()) {
        return 0;
    }
    int l = hoehe(b.getLeft());
    int r = hoehe(b.getRight());
    if (l > r) {
        return l + 1;
    }
    return r + 1;
}

