public static int anzahlAufEbene(BinTree b, int ebene) {
    if (b.isEmpty()) {
        return 0;
    }
    if (ebene == 0) {
        return 1;
    }
    int l = anzahlAufEbene(b.getLeft(), ebene - 1);
    int r = anzahlAufEbene(b.getRight(), ebene - 1);
    return l + r;
}

