public static boolean istBSTfalsch(BinTree b) {
    if (b.isEmpty()) {
        return true;
    }
    int w = (Integer) b.getItem();
    if (!b.getLeft().isEmpty()
            && (Integer) b.getLeft().getItem() >= w) {
        return false;
    }
    if (!b.getRight().isEmpty()
            && (Integer) b.getRight().getItem() <= w) {
        return false;
    }
    return istBSTfalsch(b.getLeft())
            && istBSTfalsch(b.getRight());
}

