public static boolean istBST(BinTree b) {
    return istBST(b, -1, -1);
}

// min = -1: keine Untergrenze, max = -1: keine Obergrenze
public static boolean istBST(BinTree b, int min, int max) {
    if (b.isEmpty()) {
        return true;
    }
    int w = (Integer) b.getItem();
    if (w <= min) {
        return false;
    }
    if (max != -1 && w >= max) {
        return false;
    }
    return istBST(b.getLeft(), min, w) && istBST(b.getRight(), w, max);
}
